alter table feedx_integrations.native_assistant_action_intents drop constraint native_assistant_action_intents_operation_check;
alter table feedx_integrations.native_assistant_action_intents add constraint native_assistant_action_intents_operation_check check(operation in ('prepare_marketing_draft','prepare_marketing_caption'));
do $$ declare d text:=pg_get_functiondef('public.native_assistant_action(text,jsonb)'::regprocedure); begin
if strpos(d,$old$brand uuid;$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$brand uuid;$old$,$new$brand uuid; op text;$new$);
if strpos(d,$old$p_payload->>'operation' is distinct from 'prepare_marketing_draft'$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$p_payload->>'operation' is distinct from 'prepare_marketing_draft'$old$,$new$coalesce(p_payload->>'operation','') not in ('prepare_marketing_draft','prepare_marketing_caption')$new$);
if strpos(d,$old$'{prepare_marketing_draft}',p_payload->'enabled'$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$'{prepare_marketing_draft}',p_payload->'enabled'$old$,$new$array[p_payload->>'operation'],p_payload->'enabled'$new$);
if strpos(d,$old$where actor=native_assistant_action.actor and session_id=sid$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$where actor=native_assistant_action.actor and session_id=sid$old$,$new$where native_assistant_action_intents.actor=native_assistant_action.actor and session_id=sid$new$);
if strpos(d,$old$a:=i.arguments;sid:=i.session_id;$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$a:=i.arguments;sid:=i.session_id;$old$,$new$a:=i.arguments;sid:=i.session_id;op:=i.operation;$new$);
if strpos(d,$old$a:=p_payload->'arguments';sid:=(p_payload->>'session_id')::uuid;$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$a:=p_payload->'arguments';sid:=(p_payload->>'session_id')::uuid;$old$,$new$a:=p_payload->'arguments';sid:=(p_payload->>'session_id')::uuid;op:=p_payload->>'operation';$new$);
if strpos(d,$old$c.capability_connections->'prepare_marketing_draft'$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$c.capability_connections->'prepare_marketing_draft'$old$,$new$c.capability_connections->op$new$);
if strpos(d,$old$c.ai_action_authorizations->'prepare_marketing_draft'$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$c.ai_action_authorizations->'prepare_marketing_draft'$old$,$new$c.ai_action_authorizations->op$new$);
if strpos(d,$old$jsonb_build_array('prepare_marketing_draft',1,actor,sid,a)$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$jsonb_build_array('prepare_marketing_draft',1,actor,sid,a)$old$,$new$jsonb_build_array(op,1,actor,sid,a)$new$);
if strpos(d,$old$values(actor,sid,'prepare_marketing_draft',a,fp)$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$values(actor,sid,'prepare_marketing_draft',a,fp)$old$,$new$values(actor,sid,op,a,fp)$new$);
if strpos(d,$old$result:=public.marketing_content_command(i.id,'save',org,brand,null,0,jsonb_build_object('title',a->>'title','outlet_ids','[]'::jsonb,'variants',jsonb_build_array(jsonb_build_object('channel','facebook','format','text','caption',a->>'caption','asset_ids','[]'::jsonb))));$old$)=0 then raise exception 'action_contract_changed';end if;
d:=replace(d,$old$result:=public.marketing_content_command(i.id,'save',org,brand,null,0,jsonb_build_object('title',a->>'title','outlet_ids','[]'::jsonb,'variants',jsonb_build_array(jsonb_build_object('channel','facebook','format','text','caption',a->>'caption','asset_ids','[]'::jsonb))));$old$,$new$if op='prepare_marketing_draft' then
 result:=public.marketing_content_command(i.id,'save',org,brand,null,0,jsonb_build_object('title',a->>'title','outlet_ids','[]'::jsonb,'variants',jsonb_build_array(jsonb_build_object('channel','facebook','format','text','caption',a->>'caption','asset_ids','[]'::jsonb))));
 elsif op='prepare_marketing_caption' then
 if length(a->>'title')>100 or length(trim(a->>'caption'))=0 then raise exception 'invalid_request';end if;
 result:=public.marketing_caption_save(i.id,brand,null,0,jsonb_build_object('name',a->>'title','body',a->>'caption','kind','caption','active',false));
 else raise exception 'action_unavailable';end if;$new$);
execute d;end $$;
-- Both ACTION connections and AI authorizations retain their prior settings; the new ACTION defaults off.

-- Batch transport only: delegates every decision to the canonical human authority.
create function public.native_assistant_permissions(p_codes text[]) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if auth.uid() is null or public.current_user_role_id() is null then raise exception 'admin_required' using errcode='42501';end if;
 if p_codes is null or cardinality(p_codes)>128 or exists(select 1 from unnest(p_codes) code where code is null or length(code)>120) then raise exception 'invalid_request' using errcode='22023';end if;
 return coalesce((select jsonb_object_agg(code,public.current_user_has_permission(code)) from (select distinct unnest(p_codes) code) p),'{}'::jsonb);
end $$;
revoke all on function public.native_assistant_permissions(text[]) from public,anon;
grant execute on function public.native_assistant_permissions(text[]) to authenticated;
